// Последствия активности «рыбалка» (onResult: 'hunt'), см. game.js
export const activityResults = {
  hunt: (result) => {
    const effects = [];
    for (const id of result.loot || []) effects.push({ add: id });
    if (result.outcome === 'lost') effects.push({ add: 'st_soaked' });
    const texts = {
      win: 'Добыча поднята на борт.',
      escaped: 'Тварь ушла в глубину. Лодочник сказал, что так бывает с каждым, и явно не поверил сам себе.',
      lost: 'Лодка перевернулась у самой стены. До причала пришлось добираться вплавь.',
      retreat: 'Флёр вернул лодку, не дожидаясь, пока озеро решит за него.',
    };
    return { text: texts[result.outcome] || '', effects };
  },
};
